rm -rf dist && cat > /tmp/i18n-check.mjs <<'EOF'
import { I18N } from '/home/sandbox/workspace/node_modules/@gravity-ui/i18n/build/esm/index.js';
import { readFileSync } from 'node:fs';
const en = JSON.parse(readFileSync('/home/sandbox/workspace/src/i18n/en.json', 'utf8'));
const ru = JSON.parse(readFileSync('/home/sandbox/workspace/src/i18n/ru.json', 'utf8'));
const i18n = new I18N({ lang: 'en', fallbackLang: 'en' });
i18n.registerKeysets('en', en);
i18n.registerKeysets('ru', ru);
const t = (k, p) => i18n.i18n('app', k, p);
console.log('en:', t('title'), '|', t('page_info', { page: 3 }));
i18n.setLang('ru');
console.log('ru:', t('title'), '|', t('page_info', { page: 3 }));
const keysEn = Object.keys(en.app).sort().join(','), keysRu = Object.keys(ru.app).sort().join(',');
console.log('keys match:', keysEn === keysRu);
EOF
node /tmp/i18n-check.mjs; rm -f /tmp/i18n-check.mjs; git status --short

